    26  #include <freeradius-devel/util/struct.h>
    27  #include <freeradius-devel/util/proto.h>
    28
    29  fr_pair_t *fr_raw_from_network(TALLOC_CTX *ctx, fr_dict_attr_t const *parent, uint8_t const *data, size_t data_len)
    30  {
    31          fr_pair_t *vp;
    32          fr_dict_attr_t *unknown;
    33          fr_dict_attr_t const *child;
    34
    35  #if defined(__clang_analyzer__) || !defined(NDEBUG)
    36          if (!parent->parent) return NULL; /* stupid static analyzers */
    37  #endif
    38
    39          /*
    40           *      Build an unknown attr of the entire data.
    41           */
    42          unknown = fr_dict_unknown_attr_afrom_da(ctx, parent);
    43          if (!unknown) return NULL;
    44          unknown->flags.is_raw = 1;
    45
    46          vp = fr_pair_afrom_da(ctx, unknown); /* makes a copy of 'child' */
    47          child = unknown;
    48          fr_dict_unknown_free(&child);
    49          if (!vp) return NULL;
    50
    51          if (fr_value_box_from_network(vp, &vp->data, vp->da->type, vp->da, data, data_len, true) < 0) {
    52                  talloc_free(vp);
    53                  return NULL;
    54          }
    55
    56          vp->type = VT_DATA;
    57          return vp;
    58  }
    59
    60
    61
    62  /** Convert a STRUCT to one or more VPs
    63   *
    64   */
    65  ssize_t fr_struct_from_network(TALLOC_CTX *ctx, fr_dcursor_t *cursor,
    66                                 fr_dict_attr_t const *parent, uint8_t const *data, size_t data_len,
    67                                 void *decode_ctx,
    68                                 fr_decode_value_t decode_value, fr_decode_value_t decode_tlv)
    69  {
    70          unsigned int            child_num;
    71          uint8_t const           *p = data, *end = data + data_len;
    72          fr_dict_attr_t const    *child;
    73          fr_pair_list_t          head;
    74          fr_dcursor_t            child_cursor;
    75          fr_pair_t               *vp, *key_vp;
    76          unsigned int            offset = 0;
    77
    78          fr_pair_list_init(&head);
    79          if (data_len < 1) return -1; /* at least one byte of data */
    80
    81          FR_PROTO_HEX_DUMP(data, data_len, "fr_struct_from_network");
    82
    83          /*
    84           *      Record where we were in the list when this function was called
    85           */
    86          fr_dcursor_init(&child_cursor, &head);
    87          child_num = 1;
    88          key_vp = NULL;
    89
    90          /*
    91           *      Decode structs with length prefixes.
    92           */
    93          if (da_is_length_field(parent)) {
    94                  size_t struct_len;
    95
    96                  struct_len = (p[0] << 8) | p[1];
    97                  if ((struct_len + 2) > data_len) goto unknown;
    98
    99                  data_len = struct_len + 2;
   100                  end = data + data_len;
   101                  p += 2;
   102          }
   103
   104          while (p < end) {
   105                  size_t child_length;
   106
   107                  /*
   108                   *      Go to the next child.  If it doesn't exist, we're done.
   109                   */
   110                  child = fr_dict_attr_child_by_num(parent, child_num);
   111                  if (!child) break;
   112
   113                  FR_PROTO_HEX_DUMP(p, (end - p), "fr_struct_from_network - child %s (%d)", child->name, child->attr);
   114
   115                  /*
   116                   *      Check for bit fields.
   117                   */
   118                  if (da_is_bit_field(child)) {
   119                          uint8_t array[8];
   120                          unsigned int num_bits;
   121                          uint64_t value;
   122
   123                          num_bits = offset + child->flags.length;
   124                          if ((end - p) < fr_bytes_from_bits(num_bits)) goto unknown;
   125
   126                          memset(array, 0, sizeof(array));
   127                          memcpy(&array[0], p, fr_bytes_from_bits(num_bits));
   128
   129                          if (offset > 0) array[0] &= (1 << (8 - offset)) - 1; /* mask off bits we don't care about */
   130
   131                          memcpy(&value, &array[0], sizeof(value));
   132                          value = htonll(value);
   133                          value >>= (8 - offset); /* move it to the lower bits */
   134                          value >>= (56 - child->flags.length);
   135
   136                          vp = fr_pair_afrom_da(ctx, child);
   137                          if (!vp) {
   138                                  FR_PROTO_TRACE("fr_struct_from_network - failed allocating child VP");
   139                                  goto unknown;
   140                          }
   141
   142                          switch (child->type) {
   143                                  case FR_TYPE_BOOL:
   144                                          vp->vp_bool = value;
   145                                          break;
   146
   147                                  case FR_TYPE_UINT8:
   148                                          vp->vp_uint8 = value;
   149                                          break;
   150
   151                                  case FR_TYPE_UINT16:
   152                                          vp->vp_uint16 = value;
   153                                          break;
   154
   155                                  case FR_TYPE_UINT32:
   156                                          vp->vp_uint32 = value;
   157                                          break;
   158
   159                                  case FR_TYPE_UINT64:
   160                                          vp->vp_uint64 = value;
   161                                          break;
   162
   163                                  default:
   164                                          goto unknown;
   165                          }
   166
   167                          vp->type = VT_DATA;
   168                          vp->vp_tainted = true;
   169                          fr_dcursor_append(&child_cursor, vp);
   170                          p += (num_bits >> 3); /* go to the LAST bit, not the byte AFTER the last bit */
   171                          offset = num_bits & 0x07;
   172                          child_num++;
   173                          continue;
   174                  }
   175                  offset = 0;     /* reset for non-bit-field attributes */
   176
   177                  /*
   178                   *      Decode child TLVs, according to the parent attribute.
   179                   */
   180                  if (child->type == FR_TYPE_TLV) {
   181                          ssize_t slen;
   182
   183                          fr_assert(!key_vp);
   184
   185                          if (!decode_tlv) {
   186                                  fr_strerror_const("Decoding TLVs requires a decode_tlv() function to be passed");
   187                                  return -(p - data);
   188                          }
   189
   190                          /*
   191                           *      Decode EVERYTHING as a TLV.
   192                           */
   193                          while (p < end) {
   194                                  slen = decode_tlv(ctx, &child_cursor, fr_dict_by_da(child), child, p, end - p, decode_ctx);
   195                                  if (slen < 0) goto unknown;
   196                                  p += slen;
   197                          }
   198
   199                          goto done;
   200                  }
   201
   202                  child_length = child->flags.length;
   203
   204                  /*
   205                   *      If this field overflows the input, then *all*
   206                   *      of the input is suspect.
   207                   */
   208                  if ((p + child_length) > end) {
   209                          FR_PROTO_TRACE("fr_struct_from_network - child length %zd overflows buffer", child_length);
   210                          goto unknown;
   211                  }
   212
   213                  if (!child_length) child_length = (end - p);
   214
   215                  /*
   216                   *      Magic values get the callback called.
   217                   *
   218                   *      Note that if this is an *array* of DNS labels,
   219                   *      the callback should deal with this.
   220                   */
   221                  if (decode_value) {
   222                          ssize_t slen;
   223
   224                          slen = decode_value(ctx, &child_cursor, fr_dict_by_da(child), child, p, child_length, decode_ctx);
   225                          if (slen < 0) return slen - (p - data);
   226
   227                          p += slen;      /* not always the same as child->flags.length */
   228                          child_num++;    /* go to the next child */
   229                          if (fr_dict_attr_is_key_field(child)) key_vp = fr_dcursor_tail(&child_cursor);
   230                          continue;
   231                  }
   232
   233                  /*
   234                   *      We only allow a limited number of data types
   235                   *      inside of a struct.
   236                   */
   237                  switch (child->type) {
   238                  default:
   239                          FR_PROTO_TRACE("fr_struct_from_network - unknown child type");
   240                          goto unknown;
   241
   242                  case FR_TYPE_LEAF:
   243                          break;
   244                  }
   245
   246                  vp = fr_pair_afrom_da(ctx, child);
   247                  if (!vp) {
   248                          FR_PROTO_TRACE("fr_struct_from_network - failed allocating child VP");
   249                          goto unknown;
   250                  }
   251
   252                  /*
   253                   *      No protocol-specific data types here (yet).
   254                   *
   255                   *      If we can't decode this field, then the entire
   256                   *      structure is treated as a raw blob.
   257                   */
   258                  if (fr_value_box_from_network(vp, &vp->data, vp->da->type, vp->da, p, child_length, true) < 0) {
   259                          FR_PROTO_TRACE("fr_struct_from_network - failed decoding child VP");
   260                          talloc_free(vp);
   260                          talloc_free(vp);
   261                  unknown:
   262                          fr_pair_list_free(&head);
   263
   264                          vp = fr_raw_from_network(ctx, parent, data, data_len);
   265                          if (!vp) return -1;
   266
   267                          /*
   268                           *      And append this one VP to the output cursor.
   269                           */
   270                          fr_dcursor_append(cursor, vp);
   271                          return data_len;
   272                  }
   273
   274                  vp->type = VT_DATA;
   275                  vp->vp_tainted = true;
   276                  fr_dcursor_append(&child_cursor, vp);
   277
   278                  if (fr_dict_attr_is_key_field(vp->da)) key_vp = vp;
   279
   280                  /*
   281                   *      Note that we're decoding fixed fields here.
   282                   *      So we skip the input based on the *known*
   283                   *      length, and not on the *decoded* length.
   284                   */
   285                  p += child_length;
   286                  child_num++;    /* go to the next child */
   287          }
   288
   289          /*
   290           *      Is there a substructure after this one?  If so, go
   291           *      decode it.
   292           */
   293          if (key_vp) {
   294                  ssize_t slen;
   295                  fr_dict_enum_t const *enumv;
   296                  child = NULL;
   297
   298                  FR_PROTO_HEX_DUMP(p, (end - p), "fr_struct_from_network - substruct");
   299
   300                  /*
   301                   *      Nothing more to decode, don't decode it.
   302                   */
   303                  if (p >= end) goto done;
   304
   305                  enumv = fr_dict_enum_by_value(key_vp->da, &key_vp->data);
   306                  if (enumv) child = enumv->child_struct[0];
   307
   308                  if (!child) {
   309                  unknown_child:
   310                          /*
   311                           *      Encode the unknown child as attribute
   312                           *      number 0.  This choice means we don't
   313                           *      have to look up, or keep track of, the
   314                           *      number of children of the key field.
   315                           */
   316                          child = fr_dict_unknown_afrom_fields(ctx, key_vp->da,
   317                                                               fr_dict_vendor_num_by_da(key_vp->da), 0);
   318                          if (!child) goto unknown;
   319
   320                          vp = fr_raw_from_network(ctx, child, p, end - p);
   321                          if (!vp) {
   322                                  fr_dict_unknown_free(&child);
   323                                  return -(p - data);
   324                          }
   325
   326                          fr_dcursor_append(&child_cursor, vp);
   327                          p = end;
   328                  } else {
   329                          fr_assert(child->type == FR_TYPE_STRUCT);
   330
   331                          slen = fr_struct_from_network(ctx, &child_cursor, child, p, end - p,
   332                                                        decode_ctx, decode_value, decode_tlv);
   333                          if (slen <= 0) goto unknown_child;
   334                          p += slen;
   335                  }
   336
   337                  fr_dict_unknown_free(&child);
   338
   339                  fr_dcursor_head(&child_cursor);
   340                  fr_dcursor_tail(cursor);
   341                  fr_dcursor_merge(cursor, &child_cursor);        /* Wind to the end of the new pairs */
   342
   343                  /*
   344                   *      Else return whatever we decoded.  Note that if
   345                   *      the substruct ends in a TLV, we decode only
   346                   *      the fixed-length portion of the structure.
   347                   */
   348                  return p - data;
   349          }
   350
   351  done:
   352          fr_dcursor_head(&child_cursor);
   353          fr_dcursor_tail(cursor);
   354          fr_dcursor_merge(cursor, &child_cursor);        /* Wind to the end of the new pairs */
   355
   356          return data_len;
   357  }
   358
   359
   360  /** Put bits into an output dbuff
   361   *
   362   * @param dbuff         where the bytes go
   363   * @param p             where leftover bits go
   364   * @param start_bit     start bit in the dbuff where the data goes, 0..7
   365   * @param num_bits      number of bits to write to the output, 0..55
   366   * @param data          data to write, all in the lower "num_bits" of the uint64_t variable
   367   * @return
   368   *      >= 0    the next value to pass in for start_bit
   369   *      <  0    no space or invalid start_bit or num_bits parameter
   370   */
   371  static int put_bits_dbuff(fr_dbuff_t *dbuff, uint8_t *p, int start_bit, uint8_t num_bits, uint64_t data)
   372  {
   373          uint64_t        used_bits;
   374
   375          if (start_bit < 0 || start_bit > 7) return -1;
   376          if (num_bits < 1 || num_bits > 56) return -1;
   377
   378          /* Get bits buffered in *p */
   379          used_bits = *p & (-256 >> start_bit);
   380
   381          /* Mask out all but the least significant num_bits bits of data */
   382          data &= (((uint64_t) 1) << num_bits) - 1;
   383
   384          /* Move it towards the most significant end and put used_bits at the top */
   385          data <<= (64 - (start_bit + num_bits));
   386          data |= used_bits << 56;
   387
   388          data = htonll(data);
   389
   390          start_bit += num_bits;
   391          if (start_bit > 7) FR_DBUFF_IN_MEMCPY_RETURN(dbuff, (uint8_t const *) &data, (size_t)(start_bit / 8));
   392
   393          *p = ((uint8_t *) &data)[start_bit / 8];
   394          return start_bit % 8;
   395  }
   396
   397  static int8_t pair_sort_increasing(void const *a, void const *b)
   398  {
   399          fr_pair_t const *my_a = a;
   400          fr_pair_t const *my_b = b;
   401
   402          return (my_a->da->attr > my_b->da->attr) - (my_a->da->attr < my_b->da->attr);
   403  }
   404
   405
   406  ssize_t fr_struct_to_network(fr_dbuff_t *dbuff,
   407                               fr_da_stack_t *da_stack, unsigned int depth,
   408                               fr_dcursor_t *parent_cursor, void *encode_ctx,
   409                               fr_encode_dbuff_t encode_value, fr_encode_dbuff_t encode_tlv)
   410  {
   411          fr_dbuff_t              work_dbuff = FR_DBUFF(dbuff);
   412          fr_dbuff_t              hdr_dbuff = FR_DBUFF(dbuff);
   413          int                     offset = 0;
   414          unsigned int            child_num = 1;
   415          bool                    do_length = false;
   416          uint8_t                 bit_buffer = 0;
   417          fr_pair_t const         *vp = fr_dcursor_current(parent_cursor);
   418          fr_dict_attr_t const    *key_da, *parent, *tlv = NULL;
   419          fr_dcursor_t            child_cursor, *cursor;
   420
   421          if (!vp) {
   422                  fr_strerror_printf("%s: Can't encode empty struct", __FUNCTION__);
   423                  return -1;
   424          }
   425
   426          VP_VERIFY(vp);
   427          parent = da_stack->da[depth];
   428
   429          if (parent->type != FR_TYPE_STRUCT) {
   430                  fr_strerror_printf("%s: Expected type \"struct\" got \"%s\"", __FUNCTION__,
   431                                     fr_table_str_by_value(fr_value_box_type_table, parent->type, "?Unknown?"));
   432                  return -1;
   433          }
   434
   435          /*
   436           *      If we get passed a struct VP, sort its children.
   437           */
   438          if (vp->da->type == FR_TYPE_STRUCT) {
   439                  fr_pair_t *sorted = fr_dcursor_current(parent_cursor); /* NOT const */
   440
   441                  fr_pair_list_sort(&sorted->vp_group, pair_sort_increasing);
   442                  fr_dcursor_init(&child_cursor, &sorted->vp_group);
   443                  /*
   444                   *      Build the da_stack for the new structure.
   445                   */
   446                  vp = fr_dcursor_current(&child_cursor);
   447                  fr_proto_da_stack_build(da_stack, vp ? vp->da : NULL);
   448
   449                  cursor = &child_cursor;
   450          } else {
   451                  cursor = parent_cursor;
   452          }
   453
   454          /*
   455           *      @todo - if we get a child which *eventually* has the
   456           *      given parent, then allow encoding of that struct, too.
   457           *      This allows us to encode structures automatically,
   458           *      even if key fields are omitted.
   459           */
   460          if (vp && (vp->da->parent != parent)) {
   461                  fr_strerror_printf("%s: struct encoding is missing previous attributes", __FUNCTION__);
   462                  return -1;
   463          }
   464
   465          key_da = NULL;
   466
   467          /*
   468           *      Some structs are prefixed by a 16-bit length.
   469           */
   470          if (da_is_length_field(parent)) {
   471                  FR_DBUFF_ADVANCE_RETURN(dbuff, 2);
   472                  do_length = true;
   473          }
   474
   475          for (;;) {
   476                  fr_dict_attr_t const *child;
   477
   478                  /*
   479                   *      The child attributes should be in order.  If
   480                   *      they're not, we fill the struct with zeroes.
   481                   *
   482                   *      The caller will encode TLVs.
   483                   */
   484                  child = fr_dict_attr_child_by_num(parent, child_num);
   485                  if (!child) break;
   486
   487                  /*
   488                   *      Encode child TLVs at the end of a struct.
   489                   *
   490                   *      In order to encode the child TLVs, we need to
   491                   *      know the length of "T" and "L", and we don't.
   492                   *      So just let the caller do the work.
   493                   */
   494                  if (child->type == FR_TYPE_TLV) {
   495                          if (offset != 0) goto leftover_bits;
   496
   497                          fr_assert(!key_da);
   498
   499                          tlv = child;
   500                          goto done;
   501                  }
   502
   503                  /*
   504                   *      Skipped a VP, or left one off at the end, fill the struct with zeros.
   505                   */
   506                  if (!vp || (vp->da != child)) {
   507                          /*
   508                           *      Zero out the bit field.
   509                           */
   510                          if (da_is_bit_field(child)) {
   511                                  offset = put_bits_dbuff(&work_dbuff, &bit_buffer, offset, child->flags.length, 0);
   512                                  if (offset < 0) {
   513                                          fr_strerror_printf("Failed encoding bit field %s", child->name);
   514                                          return offset;
   515                                  }
   516                                  child_num++;
   517                                  continue;
   518                          }
   519
   520                          if (fr_dict_attr_is_key_field(child)) {
   521                                  key_da = child;
   522                          }
   523
   524                          /*
   525                           *      Zero out the unused field.
   526                           */
   527                          FR_DBUFF_MEMSET_RETURN(&work_dbuff, 0, child->flags.length);
   528                          child_num++;
   529                          continue;
   530                  }
   531
   532                  /*
   533                   *      The 'struct' encoder handles bit fields.
   534                   *      They're just integers, so there's no need to
   535                   *      call the protocol encoder.
   536                   *
   537                   *      This limitation means that we can't have
   538                   *      encrypted bit fields, but that's fine.
